#define R(p, a, r) mix(a * dot(p, a), p, cos(r)) + sin(r) * cross(p, a)
#define H(h) (cos((h) * 6.3 + vec3(0, 23, 21)) * 0.5 + 0.5)
#define PI 3.141592
#define TAU 2.0 * PI
#define hue(v) (0.6 + 0.6 * cos(6.3 * (v) + vec3(0, 23, 21)))
#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))
#define COUNT 30.0
#define N 5.0
#define DISTORT 0.7
#define SQR(x) ((x) * (x))

float tt;

// Kaleidoscopic UV distortions
vec2 kalei(vec2 uv) {
    float n = N;
    float r = TAU / n;
    for (float i = 0.0; i < n; i++) {
        uv = abs(uv);
        uv *= rot(r * i - 0.09 * tt);
    }
    uv = abs(uv) - (sin(0.15 * tt) + 1.2);
    return uv;
}

// Flower SDF
float flower(vec2 uv) {
    float n = 5.0;
    float a = atan(uv.y, uv.x);
    float d = length(uv) - cos(a * n);
    return smoothstep(fwidth(d), 0.0, abs(d));
}

// Spiral pattern with distortion
vec3 spiral(vec2 uv, float i) {
    uv *= rot(i * PI + iTime * 0.33);
    uv += DISTORT * sin(5.0 * uv.yx);
    return flower(uv) * SQR(hue(i + tt * 0.2));
}

void mainImage(out vec4 O, vec2 C) {
    O = vec4(0.0);
    vec2 uv = (C - 0.5 * iResolution.xy) / iResolution.y;
    vec3 col = vec3(0.0);

    // Audio Reactivity
    float audio = texture(iChannel0, vec2(0.01, uv.y * 0.5 + 0.5)).r;
    tt = iTime + audio * 2.0;

    // Kaleidoscopic UV distortion
    vec3 r2 = normalize(vec3(uv.xy, 1.0 - dot(uv.xy, uv.xy) * 10.0));
    uv = kalei(uv * 5.0 + r2.xy);

    // Generate spiral patterns with fading
    float s = 1.0 / COUNT;
    for (float i = 0.0; i < 1.0; i += s) {
        float z = fract(i - 0.01 * tt);
        float fade = smoothstep(0.0, 0.1, 1.0 - abs(2.0 * z - 1.0));
        col += spiral(uv * z, i) * fade * (1.0 + 0.5 * audio);
    }

    col = sqrt(col); // Enhance glow intensity

    // Add depth and dynamic motion
    vec3 p, r = iResolution, d = normalize(vec3((C - 0.5 * r.xy) / r.y, 1.0));
    for (float i = 0.0, g = 0.0, e, s; ++i < 99.0; O.rgb += mix(r / r, H(log(s)), 0.7) * 0.08 * exp(-i * i * e)) {
        p = g * d * col;
        p.z -= 0.4;
        p = R(p, normalize(vec3(1.0, 1.0, 0.0)), iTime * 0.1);
        p.xy *= rot(i * PI + iTime * 0.1233);
        s = 4.0;
        for (int j = 0; j++ < 8;) {
            p = abs(p);
            p = p.x < p.y ? p.zxy : p.zyx;
            s *= e = 1.8 / min(dot(p, p), 1.3);
            p = p * e - vec3(12.0, 3.0, 3.0);
        }
        g += e = length(p.xz) / s;
    }

    // Final color adjustments
    O = pow(O, vec4(5.0));
    O.rgb *= 1.0 + 0.3 * audio; // Audio-reactive glow
}
